def _net(n, offsets, seed):
    rng = np.random.default_rng(seed)
    A = np.diag(3.0 + rng.random(n))
    for d in offsets:
        for i in range(n):
            j = i + d
            if 0 <= j < n:
                A[i, j] = rng.uniform(-1.5, 1.5)
    return A
def _state(A, k, J):
    I = np.flatnonzero(np.any(A[:, J] != 0, axis=1))
    m = np.zeros(A.shape[0])
    m[J] = np.linalg.lstsq(A[np.ix_(I, J)], (I == k).astype(float), rcond=None)[0]
    r = A @ m
    r[k] -= 1.0
    return r
